float getMaterialOpacity() {
    float alpha = 1.0;

    alpha = (texture(Texture0, vTexCoord1).a);
    if (uOpacityInvert == 1) alpha = 1.0 - alpha;

    alpha *= uOpacityFactor;

    return alpha;
}

float pseudoRandom(const in vec2 fragCoord) {
    vec3 p3  = fract(vec3(fragCoord.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.x + p3.y) * p3.z);
}

float interleavedGradientNoise(const in vec2 fragCoord, const in float frameMod) {
    vec3 magic = vec3(0.06711056, 0.00583715, 52.9829189);
    return fract(magic.z * fract(dot(fragCoord.xy + frameMod * vec2(47.0, 17.0) * 0.695, magic.xy)));
}

float ditheringNoise(const in vec2 fragCoord, const in float frameMod) {

    float fm = frameMod;
    float dither5 = fract((fragCoord.x + fragCoord.y * 2.0 - 1.5 + fm) / 5.0);
    float noise = fract(dot(vec2(171.0, 231.0) / 71.0, fragCoord.xy));
    return (dither5 * 5.0 + noise) * (1.2 / 6.0);
}

void ditheringMaskingDiscard(
const in vec4 fragCoord,
const in int dithering,
const in float alpha,
const in float factor,

const in float thinLayer,

const in float frameMod,
const in vec2 nearFar,

const in vec4 halton) {

    float rnd;

    if (thinLayer == 0.0) {
        float linZ = (1.0 / fragCoord.w - nearFar.x) / (nearFar.y - nearFar.x);
        float sliceZ = floor(linZ * 500.0) / 500.0;
        rnd = interleavedGradientNoise(fragCoord.xy + sliceZ, frameMod);
        } else {
        rnd = pseudoRandom(fragCoord.xy + halton.xy * 1000.0 + fragCoord.z * (abs(halton.z) == 2.0 ? 1000.0 : 1.0));
    }

    if ((alpha * factor) < rnd) discard;
}

vec4 encodeFloatRGBA( float v ) {
    vec4 enc = vec4(1.0, 255.0, 65025.0, 16581375.0) * v;
    enc = fract(enc);
    enc -= enc.yzww * vec4(1.0 / 255.0, 1.0 / 255.0, 1.0 / 255.0, 0.0);
    return enc;
}

out vec4 glFragColor_0;
void main() {

    if (getMaterialOpacity() < 9.9999e-1) discard;

    glFragColor_0 = encodeFloatRGBA((-vViewVertex.z - uShadowDepthRange.x) / (uShadowDepthRange.y - uShadowDepthRange.x));
}

#version 300 es
precision highp float;

in vec3 Vertex;

out vec2 vTexCoord0;
#define SHADER_NAME MaterialPacker

void main(void) {
    gl_Position = vec4(Vertex * 2.0 - 1.0, 1.0);
    vTexCoord0 = Vertex.xy;
}

#version 300 es
precision highp float;

uniform ivec4 uReadPacking;
uniform sampler2D uTexture0;
uniform sampler2D uTexture1;
uniform sampler2D uTexture2;
uniform sampler2D uTexture3;

in vec2 vTexCoord0;
#define SHADER_NAME MaterialPacker

out vec4 glFragColor_0;
void main(void) {
    if (uReadPacking.x == 4) {
        glFragColor_0.rg = texture(uTexture0, vTexCoord0).rg;
        if (uReadPacking.y == 4) {
            glFragColor_0.ba = texture(uTexture1, vTexCoord0).rg;
            } else {
            glFragColor_0.b = uReadPacking.y == 0 ? texture(uTexture1, vTexCoord0).r : texture(uTexture1, vTexCoord0).a;
            glFragColor_0.a = uReadPacking.z == 0 ? texture(uTexture2, vTexCoord0).r : texture(uTexture2, vTexCoord0).a;
        }

        } else if (uReadPacking.x == 3) {

        glFragColor_0.rgb = texture(uTexture0, vTexCoord0).aaa;
        glFragColor_0.a = uReadPacking.y == 0 ? texture(uTexture1, vTexCoord0).r : texture(uTexture1, vTexCoord0).a;

        } else if (uReadPacking.x == 2) {

        glFragColor_0.rgb = texture(uTexture0, vTexCoord0).rgb;
        glFragColor_0.a = uReadPacking.y == 0 ? texture(uTexture1, vTexCoord0).r : texture(uTexture1, vTexCoord0).a;

        } else {

        glFragColor_0.r = uReadPacking.x == 0 ? texture(uTexture0, vTexCoord0).r : texture(uTexture0, vTexCoord0).a;
        glFragColor_0.g = uReadPacking.y == 0 ? texture(uTexture1, vTexCoord0).r : texture(uTexture1, vTexCoord0).a;
        glFragColor_0.b = uReadPacking.z == 0 ? texture(uTexture2, vTexCoord0).r : texture(uTexture2, vTexCoord0).a;
        glFragColor_0.a = uReadPacking.w == 0 ? texture(uTexture3, vTexCoord0).r : texture(uTexture3, vTexCoord0).a;
    }
}

