int decodeProfile(const in vec4 pack) {
    float packValue = floor(pack.b * 255.0 + 0.5);

    float profile = mod(packValue, 2.0);
    profile += mod(packValue - profile, 4.0);
    return int(profile);
}

float decodeDepth(const in vec4 pack) {
