,const in float jitter) {

    bool earlyOut = false;

    float shadow = 1.0;

    if (!lighted) {
        shadow = 0.0;
        earlyOut = true;
    }

    if (shadowDepthRange.x == shadowDepthRange.y) {
        earlyOut = true;
    }

