    float VoH =  clamp(dot(eyeLightDir, H), 0., 1.);

    float D = D_GGX(precomputeGGX, NoH);
    float V = V_SmithCorrelated(precomputeGGX, NoL);
    vec3 F = F_Schlick(specular, f90, VoH);

    return (D * V * 3.141593) * F;
