    }

    vec4 accumColorN =  (texture(TexturePrevious, (floor((min(gTexCoord, 1.0 - 1e+0 / uTexturePreviousSize.xy)) * uTexturePreviousSize) + 0.5) * uTexturePreviousRatio / uTexturePreviousSize, -99999.0)).rgba;

