vec3 reconstructVSPosition(const in vec2 uv, const in vec4 corners0, const in vec4 corners1, const in float depth) {
    vec2 finalUv = uv;

    vec4 AB = mix(corners0, corners1, vec4(finalUv.x));

    return vec3(mix(AB.xy, AB.zw, vec2(finalUv.y)), 1.0) * depth;
