    lightDiffuse *= ccAttenuation;
    lightSpecular = ccSpecular + lightSpecular * ccAttenuation;

    shadow = shadowReceive(lighted, modelNormal, vModelVertex, Texture7, uShadow_Texture0_renderSize, uShadow_Texture3_projection, uShadow_Texture3_viewRight, uShadow_Texture3_viewUp, uShadow_Texture3_viewLook, uShadow_Texture3_depthRange, uShadowReceive3_bias, uShadow_Texture3_mapSize,  uStaticFrameNumShadow3);

    lightDiffuse *= shadow;
    lightSpecular *= shadow;

    diffuse += lightDiffuse;
    specular += lightSpecular;

    vec3 frag = diffuse + specular;
    frag = uEmitMultiplicative == 1 ? frag * materialEmit : frag + materialEmit;

    if (uOutputLinear != 1) frag = linearTosRGB(frag);

    glFragColor_0 = encodeRGBM(frag, uRGBMRange);
}

