#version 300 es
precision highp float;

in vec4 Vertex;
in vec2 Normal;
in vec2 TexCoord1;

uniform float uDisplay2D;
uniform float uPointSize;
uniform mat3 uModelNormalMatrix;
uniform mat3 uModelViewNormalMatrix;
uniform mat4 uModelMatrix;
uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat4 uViewMatrix;
uniform vec2 uGlobalTexRatio;
uniform vec2 uGlobalTexSize;
uniform vec3 uQVS;
uniform vec3 uQVT;
uniform vec4 uHalton;
uniform vec4 uQUV1;

out vec3 vViewNormal;
out vec3 vModelNormal;
out vec3 vModelVertex;
out vec2 vTexCoord1;
out vec4 vViewVertex;
#define SHADER_NAME PBR_Blend(RIM_BLUR_001)

void main() {
    vTexCoord1 = TexCoord1.xy * uQUV1.zw + uQUV1.xy;

    vec3 localVertex = Vertex.xyz;
    localVertex += Vertex.w;
    localVertex = localVertex * uQVS / vec3(1.544590323971317e-1,9.596370777060687e-1,1.5235399086210746e-1).zxy + uQVT;

    vModelVertex = (uModelMatrix * vec4(localVertex, 1.0)).xyz;

    vec3 localNormal = Normal.xyy;
    localNormal.z = dot(localNormal.xy, localNormal.xy); localNormal.xyz = vec3(2.0 * localNormal.xy * sqrt(1.0 - localNormal.z), 1.0 - 2.0 * localNormal.z);;

    vModelNormal = uModelNormalMatrix * localNormal;

    vViewNormal = uModelViewNormalMatrix * localNormal;

    vViewVertex = uModelViewMatrix * vec4(localVertex, 1.0);

    mat4 jitteredProjection = uProjectionMatrix;
    jitteredProjection[2].xy += (1.0 - uDisplay2D) * (uHalton.xy * uGlobalTexRatio.xy / uGlobalTexSize.xy);

    gl_Position = jitteredProjection * vViewVertex;

    gl_PointSize = min(64.0, max(1.0, -uPointSize / vViewVertex.z));

}

