    E.y = fract(E.x * 52.9829189);

    E.y = mix(E.y, 1.0, 0.7);

    float phi = 2.0 * 3.14159 * E.x;

    float cosTheta = pow(max(E.y, 0.000001), rough4 / (2.0 - rough4));
    float sinTheta = sqrt(1.0 - cosTheta * cosTheta);

