    result.x = fetchDepthLod(uv0.xy, pixelSizePowLevel);
    result.y = fetchDepthLod(uv0.zw, pixelSizePowLevel);
    result.z = fetchDepthLod(uv1.xy, pixelSizePowLevel);
    result.w = fetchDepthLod(uv1.zw, pixelSizePowLevel);
