        blur +=  (vec4(decodeRGBM(texture(TextureDofBlurCircular, (min(uv + off.yy / uTextureDofBlurCircularSize, 1.0 - 1e+0 / uTextureDofBlurCircularSize.xy)) * uTextureDofBlurCircularRatio), uRGBMRange), 1.0)).rgb;
        blur +=  (vec4(decodeRGBM(texture(TextureDofBlurCircular, (min(uv + off.xy / uTextureDofBlurCircularSize, 1.0 - 1e+0 / uTextureDofBlurCircularSize.xy)) * uTextureDofBlurCircularRatio), uRGBMRange), 1.0)).rgb;
        blur +=  (vec4(decodeRGBM(texture(TextureDofBlurCircular, (min(uv + off.yx / uTextureDofBlurCircularSize, 1.0 - 1e+0 / uTextureDofBlurCircularSize.xy)) * uTextureDofBlurCircularRatio), uRGBMRange), 1.0)).rgb;
        blur /= 5.0;
    }

    vec2 uvNearest = (floor(uv * uTextureDofNearDilateVSize) + 0.5) / uTextureDofNearDilateVSize;
    float coc = abs(min( (texture(TextureDofNearDilateV, (min(uvNearest, 1.0 - 1e+0 / uTextureDofNearDilateVSize.xy)) * uTextureDofNearDilateVRatio)).a * 2.0 - 1.0, texDepthToCoC(depthPacked)));

    float cocLower = 0.05;
    float cocHigher = 0.3;

    return vec4(mix(color, blur, smoothstep(cocLower, cocHigher, coc)), 1.0);
}

out vec4 glFragColor_0;
void main(void) {
    gTexCoord = gl_FragCoord.xy / uTextureOutputSize.xy;
    vec4 color = dofCombine();

    color.rgb = linearTosRGB(color.rgb);

    glFragColor_0 = color;
}

