vec3 reconstructVSPosition(const in vec2 uv, const in vec4 corners0, const in vec4 corners1, const in float depth) {
    vec2 finalUv = uv;

    vec4 AB = mix(corners0, corners1, vec4(finalUv.x));

    return vec3(mix(AB.xy, AB.zw, vec2(finalUv.y)), 1.0) * depth;
}

vec3 closestFragment(const in vec2 uv, const in vec2 texelSize) {

    float d;
    vec2 size = 2.0 * texelSize;
    vec3 dmin = vec3(0.0, 0.0, 0.0);

    dmin.z = decodeDepth( (texture(TextureDepth, (min(uv + vec2( 0.0, 0.0), 1.0 - 1e+0 / uTextureDepthSize.xy)) * uTextureDepthRatio)));;
    d = decodeDepth( (texture(TextureDepth, (min(uv + vec2(  -size.x,  size.y), 1.0 - 1e+0 / uTextureDepthSize.xy)) * uTextureDepthRatio)));;  if(d < dmin.z) dmin = vec3(  -size.x,   size.y, d);;
    d = decodeDepth( (texture(TextureDepth, (min(uv + vec2(  size.x,  size.y), 1.0 - 1e+0 / uTextureDepthSize.xy)) * uTextureDepthRatio)));;  if(d < dmin.z) dmin = vec3(  size.x,   size.y, d);;
    d = decodeDepth( (texture(TextureDepth, (min(uv + vec2(  -size.x,  -size.y), 1.0 - 1e+0 / uTextureDepthSize.xy)) * uTextureDepthRatio)));;  if(d < dmin.z) dmin = vec3(  -size.x,   -size.y, d);;
    d = decodeDepth( (texture(TextureDepth, (min(uv + vec2(  size.x,  -size.y), 1.0 - 1e+0 / uTextureDepthSize.xy)) * uTextureDepthRatio)));;  if(d < dmin.z) dmin = vec3(  size.x,   -size.y, d);;

    return vec3(uv + dmin.xy, dmin.z);
}

vec4 clip_aabb_opti(const in vec4 minimum, const in vec4 maximum, const in vec4 color) {
    const float eps = 0.00000001;

    vec4 center = 0.5 * (maximum + minimum);
    vec4 extents = 0.5 * (maximum - minimum) + eps;
    vec4 offset = color - center;

    vec4 ts = abs(offset / extents);
    float t = max(max(ts.r, ts.g), max(ts.b, ts.a));
    return center + offset / max(1.0, t);

}

vec4 taa(const in vec2 ssVel, const in vec2 texelSize) {
    vec2 uv = gTexCoord;

    vec4 tl =  (texture(TextureInput, (min(uv + vec2(-texelSize.x, texelSize.y), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));
    vec4 t  =  (texture(TextureInput, (min(uv + vec2(0.0, texelSize.y), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));
    vec4 tr =  (texture(TextureInput, (min(uv + vec2(texelSize.x, texelSize.y), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));

    vec4 ml =  (texture(TextureInput, (min(uv + vec2(-texelSize.x, 0.0), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));
    vec4 m  =  (texture(TextureInput, (min(uv, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));
    vec4 mr =  (texture(TextureInput, (min(uv + vec2(texelSize.x, 0.0), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));

    vec4 bl =  (texture(TextureInput, (min(uv + vec2(-texelSize.x, -texelSize.y), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));
    vec4 b  =  (texture(TextureInput, (min(uv + vec2(0.0, -texelSize.y), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));
    vec4 br =  (texture(TextureInput, (min(uv + vec2(texelSize.x, -texelSize.y), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));

    vec4 corners = 2.0 * (tr + bl + br + tl) - 2.0 * m;
    m += (m - (corners * 0.166667)) * 2.718282 * 0.3;
    m = max(vec4(0.0), m);

    vec4 cmin5 = min(mr, min(m, min(ml, min(t, b))));
    vec4 cmin = min(cmin5, min(tl, min(tr, min(bl, br))));

    vec4 cmax5 = max(mr, max(m, max(ml, max(t, b))));
    vec4 cmax = max(cmax5, max(tl, max(tr, max(bl, br))));

    cmin = 0.5 * (cmin + cmin5);
    cmax = 0.5 * (cmax + cmax5);

    vec4 previousColor =  (texture(TexturePrevious, (min(uv - ssVel, 1.0 - 1e+0 / uTexturePreviousSize.xy)) * uTexturePreviousRatio));
    previousColor = clip_aabb_opti(cmin, cmax, previousColor);

    float lum0 = getLuminance(m.rgb);
    float lum1 = getLuminance(previousColor.rgb);
    float diff = abs(lum0 - lum1) / max(lum0, max(lum1, 0.2));
    float unbiased_weight = 1.0 - diff;
    float feedback = mix(0.88, 0.97, unbiased_weight * unbiased_weight);

    return mix(m, previousColor, feedback);
}

vec2 computeSSVelocity(const in vec2 pixelPos, const in vec3 vsPos, const in mat4 motionMatrix, const in bool rightEye) {
    vec4 screenSpaceNDCPrevPosition = motionMatrix * vec4(vsPos, 1.0);
    vec2 ndcPrev = screenSpaceNDCPrevPosition.xy / screenSpaceNDCPrevPosition.w;

    if(ndcPrev.x >= 1.0 || ndcPrev.x <= -1.0 ||
    ndcPrev.y >= 1.0 || ndcPrev.y <= -1.0)
    return vec2(0.0);

    vec2 ndcCurrent = pixelPos * 2.0 - 1.0;

    return 0.5 * (ndcCurrent - ndcPrev);
}

vec4 computeTaa(const in mat4 motionMatrix, const in vec4 corners0, const in vec4 corners1, const in bool rightVR) {
    vec2 uv = gTexCoord;
    float haltz = abs(uHalton.z);
    if (haltz == 1.0) {
        vec2 texelSize = vec2(1.0) / uTextureInputSize;
        vec3 closest = closestFragment(uv, texelSize);

        if (closest.z >= 1.0
        && decodeAlpha( (texture(TextureDepth, (min(closest.xy, 1.0 - 1e+0 / uTextureDepthSize.xy)) * uTextureDepthRatio))) == 0.0
        ) {

            return  (texture(TextureInput, (min(uv - 0.5 * uHalton.xy * texelSize, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));
        }

        float depth = -(uNearFar.x + (uNearFar.y - uNearFar.x) * closest.z);
        vec3 viewSpace = reconstructVSPosition(closest.xy, corners0, corners1, depth);
        vec2 ssVel = computeSSVelocity(closest.xy, viewSpace, motionMatrix, rightVR);

        return taa(ssVel, texelSize);
    }

    return supersample();
}

vec4 supersampleTaa() {
    if (uTaaEnabled == 0.0) {
        return supersample();
    }

    return computeTaa(uTaaMotionMatrixLeft, uTaaCornersCSLeft[0], uTaaCornersCSLeft[1], false);
}

out vec4 glFragColor_0;
void main(void) {
    gTexCoord = gl_FragCoord.xy / uTextureOutputSize.xy;
    vec4 color = supersampleTaa();

    glFragColor_0 = color;
}

