    float gradient = max(abs(gradientN), abs(gradientS));
    if(pairN) lengthSign = -lengthSign;
    float subpixC = clamp(abs(subpixB) * subpixRcpRange, 0.0, 1.0);

    vec2 posB = posM.xy;
    vec2 offNP;
    offNP.x = (!horzSpan) ? 0.0 : fxaaQualityRcpFrame.x;
    offNP.y = ( horzSpan) ? 0.0 : fxaaQualityRcpFrame.y;
    if(!horzSpan) posB.x += lengthSign * 0.5;
    if( horzSpan) posB.y += lengthSign * 0.5;

    vec2 posN;
    posN.x = posB.x - offNP.x;
    posN.y = posB.y - offNP.y;
    vec2 posP;
    posP.x = posB.x + offNP.x;
    posP.y = posB.y + offNP.y;
    float subpixD = ((-2.0)*subpixC) + 3.0;
    float lumaEndN =  (texture(TextureInput, (min(posN, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).y;
    float subpixE = subpixC * subpixC;
    float lumaEndP =  (texture(TextureInput, (min(posP, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).y;

    if(!pairN) lumaNN = lumaSS;
    float gradientScaled = gradient * 1.0/4.0;
    float lumaMM = lumaM - lumaNN * 0.5;
    float subpixF = subpixD * subpixE;
    bool lumaMLTZero = lumaMM < 0.0;

    lumaEndN -= lumaNN * 0.5;
    lumaEndP -= lumaNN * 0.5;
    bool doneN = abs(lumaEndN) >= gradientScaled;
    bool doneP = abs(lumaEndP) >= gradientScaled;
    if(!doneN) posN.x -= offNP.x * 1.5;
    if(!doneN) posN.y -= offNP.y * 1.5;
    bool doneNP = (!doneN) || (!doneP);
    if(!doneP) posP.x += offNP.x * 1.5;
    if(!doneP) posP.y += offNP.y * 1.5;

    if(doneNP) {
        if(!doneN) lumaEndN =  (texture(TextureInput, (min(posN.xy, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).y;
        if(!doneP) lumaEndP =  (texture(TextureInput, (min(posP.xy, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).y;
        if(!doneN) lumaEndN = lumaEndN - lumaNN * 0.5;
        if(!doneP) lumaEndP = lumaEndP - lumaNN * 0.5;
        doneN = abs(lumaEndN) >= gradientScaled;
        doneP = abs(lumaEndP) >= gradientScaled;
        if(!doneN) posN.x -= offNP.x * 2.0;
        if(!doneN) posN.y -= offNP.y * 2.0;
        doneNP = (!doneN) || (!doneP);
        if(!doneP) posP.x += offNP.x * 2.0;
        if(!doneP) posP.y += offNP.y * 2.0;

        if(doneNP) {
            if(!doneN) lumaEndN =  (texture(TextureInput, (min(posN.xy, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).y;
            if(!doneP) lumaEndP =  (texture(TextureInput, (min(posP.xy, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).y;
            if(!doneN) lumaEndN = lumaEndN - lumaNN * 0.5;
            if(!doneP) lumaEndP = lumaEndP - lumaNN * 0.5;
            doneN = abs(lumaEndN) >= gradientScaled;
            doneP = abs(lumaEndP) >= gradientScaled;
            if(!doneN) posN.x -= offNP.x * 4.0;
            if(!doneN) posN.y -= offNP.y * 4.0;
            doneNP = (!doneN) || (!doneP);
            if(!doneP) posP.x += offNP.x * 4.0;
            if(!doneP) posP.y += offNP.y * 4.0;

            if(doneNP) {
                if(!doneN) lumaEndN =  (texture(TextureInput, (min(posN.xy, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).y;
                if(!doneP) lumaEndP =  (texture(TextureInput, (min(posP.xy, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).y;
                if(!doneN) lumaEndN = lumaEndN - lumaNN * 0.5;
                if(!doneP) lumaEndP = lumaEndP - lumaNN * 0.5;
                doneN = abs(lumaEndN) >= gradientScaled;
                doneP = abs(lumaEndP) >= gradientScaled;
                if(!doneN) posN.x -= offNP.x * 12.0;
                if(!doneN) posN.y -= offNP.y * 12.0;
                doneNP = (!doneN) || (!doneP);
                if(!doneP) posP.x += offNP.x * 12.0;
                if(!doneP) posP.y += offNP.y * 12.0;

            }

        }

    }

    float dstN = posM.x - posN.x;
    float dstP = posP.x - posM.x;
    if(!horzSpan) dstN = posM.y - posN.y;
    if(!horzSpan) dstP = posP.y - posM.y;

    bool goodSpanN = (lumaEndN < 0.0) != lumaMLTZero;
    float spanLength = (dstP + dstN);
    bool goodSpanP = (lumaEndP < 0.0) != lumaMLTZero;
    float spanLengthRcp = 1.0/spanLength;

    bool directionN = dstN < dstP;
    float dst = min(dstN, dstP);
    bool goodSpan = directionN ? goodSpanN : goodSpanP;
    float subpixG = subpixF * subpixF;
    float pixelOffset = (dst * (-spanLengthRcp)) + 0.5;
    float subpixH = subpixG * fxaaQualitySubpix;

    float pixelOffsetGood = goodSpan ? pixelOffset : 0.0;
    float pixelOffsetSubpix = max(pixelOffsetGood, subpixH);
    if(!horzSpan) posM.x += pixelOffsetSubpix * lengthSign;
    if( horzSpan) posM.y += pixelOffsetSubpix * lengthSign;

    return  (texture(TextureInput, (min(posM, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio));
}

int decodeProfile(const in vec4 pack) {
    float packValue = floor(pack.b * 255.0 + 0.5);

    float profile = mod(packValue, 2.0);
    profile += mod(packValue - profile, 4.0);
    return int(profile);
}

float decodeDepth(const in vec4 pack) {
    if(decodeProfile(pack) == 0){
        const vec3 decode = 1.0 / vec3(1.0, 255.0, 65025.0);
        return dot(pack.rgb, decode);
    }

    return pack.r + pack.g / 255.0;
}

float decodeScatter(const in vec4 pack) {

    float scatter = (4.0 / 255.0) * floor(pack.b * 255.0 * 0.25);

    return scatter * 1.0119047619;
}

float decodeAlpha(const in vec4 pack) {
    return pack.a;
}

float distanceToDepth(const in sampler2D depth, const in vec2 uv, const in vec4 viewPos, const vec2 nearFar) {
    float fragDepth = clamp( (-viewPos.z * viewPos.w - nearFar.x) / (nearFar.y - nearFar.x), 0.0, 1.0);
    return fragDepth - decodeDepth(texture(depth, uv));
}

vec3 sharpColorFactor(const in vec3 color, const float sharp) {
    vec2 off = uPixelRatio.xy / uTextureInputSize.xy;

    vec3 rgbNW =  (texture(TextureInput, (min(gTexCoord + off * vec2(-1.0, -1.0), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).rgb;
    vec3 rgbSE =  (texture(TextureInput, (min(gTexCoord + off * vec2(1.0, 1.0), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).rgb;
    vec3 rgbNE =  (texture(TextureInput, (min(gTexCoord + off * vec2(1.0, -1.0), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).rgb;
    vec3 rgbSW =  (texture(TextureInput, (min(gTexCoord + off * vec2(-1.0, 1.0), 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)).rgb;

    return color + sharp * (4.0 * color - rgbNW - rgbNE - rgbSW - rgbSE);
}

vec4 sharpen(const in vec4 color) {
    float alpha = decodeAlpha( (texture(TextureDepth, (min(gTexCoord, 1.0 - 1e+0 / uTextureDepthSize.xy)) * uTextureDepthRatio)));
    if( alpha == 0.0 ) {
        return vec4(color.rgb,1.0);
    }

    return vec4(sharpColorFactor(color.rgb, uSharpFactor * alpha), color.a);
}

vec4 sharpen() {
    return sharpen( (texture(TextureInput, (min(gTexCoord, 1.0 - 1e+0 / uTextureInputSize.xy)) * uTextureInputRatio)));
}

vec4 dofCross(const in vec4 color) {
    float ratio = uTextureInputSize.y / uTextureInputSize.x;
    float dist = distance(vec2(uDofCross.x, uDofCross.y * ratio), gTexCoord * vec2(1.0, ratio));
    float widthCircle = uPixelRatio.x / uTextureInputSize.x;
    return vec4(mix(color.rgb, vec3(1.0), abs(dist - 60.0 * widthCircle) > widthCircle ? 0.0 : uDofCross.z), color.a);
}

out vec4 glFragColor_0;
void main(void) {
    gTexCoord = gl_FragCoord.xy / uTextureOutputSize.xy;
    vec4 color = fxaa();
    color = sharpen(color);
    color = dofCross(color);

    glFragColor_0 = color;
}

